const allJobs = [];
const seen = new Set();

for (const item of $input.all()) {
  const raw = item.json;
  if (!raw || typeof raw !== 'object') continue;

  let job = {};

  // RemoteOK: array root, has 'slug' or 'position'
  if (raw.slug !== undefined || raw.position !== undefined) {
    if (raw.legal) continue; // skip metadata row
    job = {
      job_title: raw.position || raw.title || '',
      company: raw.company || '',
      job_url: raw.url || `https://remoteok.com/remote-jobs/${raw.slug}`,
      source: 'RemoteOK',
      location_text: raw.location || 'Worldwide',
      salary: raw.salary_min ? `$${raw.salary_min}-$${raw.salary_max}/yr` : (raw.salary || ''),
      description: (raw.description || '').replace(/<[^>]+>/g, '').substring(0, 3000),
      posted_date: raw.date || '',
      tags: Array.isArray(raw.tags) ? raw.tags.join(', ') : ''
    };
  }
  // Remotive: has 'candidate_required_location'
  else if (raw.candidate_required_location !== undefined) {
    job = {
      job_title: raw.title || '',
      company: raw.company_name || '',
      job_url: raw.url || '',
      source: 'Remotive',
      location_text: raw.candidate_required_location || 'Worldwide',
      salary: raw.salary || '',
      description: (raw.description || '').replace(/<[^>]+>/g, '').substring(0, 3000),
      posted_date: raw.publication_date || '',
      tags: Array.isArray(raw.tags) ? raw.tags.join(', ') : (raw.job_type || '')
    };
  }
  // Remotive wrapper: { jobs: [...] }
  else if (Array.isArray(raw.jobs)) {
    for (const j of raw.jobs) {
      allJobs.push({ json: { ...j, _source_wrapper: 'remotive' } });
    }
    continue;
  }
  // RemoteOK is also returned as an array at root, but n8n splits it
  // RSS feed: has 'isoDate' or 'pubDate' and 'link'
  else if (raw.link !== undefined && (raw.isoDate !== undefined || raw.pubDate !== undefined)) {
    const t = raw.title || '';
    const parts = t.includes(' at ') ? t.split(' at ') : [t, ''];
    job = {
      job_title: parts.slice(0, -1).join(' at ').trim() || t,
      company: parts[parts.length - 1].trim() || raw.creator || raw['dc:creator'] || '',
      job_url: raw.link || raw.guid || '',
      source: raw._source || 'RSS',
      location_text: raw.location || '',
      salary: '',
      description: (raw.contentSnippet || raw.content || raw.summary || '').replace(/<[^>]+>/g, '').substring(0, 3000),
      posted_date: raw.isoDate || raw.pubDate || '',
      tags: Array.isArray(raw.categories) ? raw.categories.join(', ') : ''
    };
  }
  // Himalayas or generic JSON API
  else {
    job = {
      job_title: raw.title || raw.job_title || raw.name || raw.role || '',
      company: raw.company || raw.company_name || raw.organization || raw.employer || '',
      job_url: raw.url || raw.apply_url || raw.link || raw.job_url || raw.applyUrl || '',
      source: raw._source || 'API',
      location_text: raw.location || raw.location_text || raw.remote_location || raw.country || '',
      salary: raw.salary || raw.compensation || raw.pay || raw.salary_range || '',
      description: (raw.description || raw.body || raw.job_description || raw.summary || '').replace(/<[^>]+>/g, '').substring(0, 3000),
      posted_date: raw.created_at || raw.date || raw.posted_date || raw.published_at || '',
      tags: Array.isArray(raw.tags) ? raw.tags.join(', ') : (raw.tags || raw.skills || raw.categories || '')
    };
  }

  if (!job.job_title && !job.job_url) continue;

  job.job_id = job.job_url || `${job.company}__${job.job_title}`.replace(/[^a-z0-9]/gi, '_').toLowerCase();
  job.date_found = new Date().toISOString().split('T')[0];

  if (seen.has(job.job_id)) continue;
  seen.add(job.job_id);

  allJobs.push({ json: job });
}

return allJobs.length > 0 ? allJobs : [{ json: { _empty: true } }];

// Compare incoming new jobs against existing sheet data
let existingUrls = new Set();
let existingKeys = new Set();

try {
  const existingData = $('Read Existing Jobs').all();
  for (const item of existingData) {
    if (item.json.job_url) existingUrls.add(item.json.job_url.trim());
    if (item.json.company && item.json.job_title) {
      existingKeys.add(`${item.json.company}__${item.json.job_title}`.toLowerCase().trim());
    }
  }
} catch (e) {
  // First run — sheet empty, proceed with all jobs
}

const newJobs = [];
for (const item of $input.all()) {
  if (item.json._empty) continue;
  const job = item.json;
  const key = `${job.company}__${job.job_title}`.toLowerCase().trim();
  if (existingUrls.has((job.job_url || '').trim())) continue;
  if (existingKeys.has(key)) continue;
  newJobs.push(item);
}

return newJobs.length > 0 ? newJobs : [{ json: { _no_new_jobs: true } }];

const REJECT = [
  /\bus\s*only\b/i, /\bunited\s*states\s*only\b/i, /\bcanada\s*only\b/i,
  /\buk\s*only\b/i, /\bgb\s*only\b/i, /\beu\s*only\b/i, /\beurope\s*only\b/i,
  /\baustralia\s*only\b/i, /\bmust\s+be\s+based\s+in\b/i,
  /\bmust\s+live\s+in\b/i, /\bmust\s+be\s+authorized\s+to\s+work\s+in\b/i,
  /\bwork\s+authorization\s+required\b/i, /\blocal\s+work\s+permit\b/i,
  /\bhybrid\b/i, /\bonsite\b/i, /\bon-site\b/i, /\bin\s+office\b/i,
  /\boffice\s+required\b/i, /\bremote\s+within\b.*\bonly\b/i,
  /\bfixed\s+us\s+hours\b/i, /\bfixed\s+eu\s+hours\b/i,
  /\bauthorized\s+to\s+work\s+in\s+the\s+us\b/i,
  /\beligible\s+to\s+work\s+in\s+the\s+uk\b/i
];

const KEEP = [
  /\bworldwide\b/i, /\bglobal\s+remote\b/i, /\bwork\s+from\s+anywhere\b/i,
  /\banywhere\s+in\s+the\s+world\b/i, /\bapac\b/i,
  /\binternational\s+contractors?\b/i, /\bcontractor\s+role\b/i,
  /\bb2b\s+contractor\b/i, /\bdeel\.com\b/i, /\bremote\.com\b/i,
  /\boyster\b/i, /\beor\b/i, /\bemployer\s+of\s+record\b/i,
  /\bremote[\s-]first\b/i, /\bdistributed\s+team\b/i,
  /\binternational\s+team\b/i, /\bglobal\s+team\b/i
];

const out = [];
for (const item of $input.all()) {
  if (item.json._no_new_jobs) continue;
  const job = item.json;
  const text = `${job.description} ${job.location_text} ${job.job_title}`;
  const hasKeep = KEEP.some(p => p.test(text));
  const hasReject = REJECT.some(p => p.test(text));
  if (hasReject && !hasKeep) continue;
  out.push(item);
}
return out.length > 0 ? out : [];

