// Claude AI response comes in. Original job fields are in the batch context.
// n8n httpRequest passes the response body as json; original input fields are lost.
// We use $('Split in Batches') to recover the original batch items by position.
const aiItems = $input.all();
const results = [];

let batchItems = [];
try {
  batchItems = $('Split in Batches').all();
} catch (e) { /* fallback: no original data */ }

for (let i = 0; i < aiItems.length; i++) {
  const aiItem = aiItems[i];
  const originalJob = batchItems[i] ? batchItems[i].json : {};

  let ai = {
    taiwan_eligible: 'unclear',
    reason: 'AI check failed',
    location_risk: 'medium',
    timezone_risk: 'medium',
    contractor_possible: 'unclear',
    decision: 'manual_check'
  };

  try {
    const content = aiItem.json.content;
    if (Array.isArray(content) && content[0] && content[0].text) {
      const rawText = content[0].text.trim();
      const jsonMatch = rawText.match(/\{[\s\S]*\}/);
      if (jsonMatch) ai = JSON.parse(jsonMatch[0]);
    }
  } catch (e) { /* keep defaults */ }

  if (ai.decision === 'reject' || ai.taiwan_eligible === 'no') continue;

  results.push({ json: { ...originalJob, _ai: ai } });
}

return results;

const ASYNC_REJECT = [
  /\bstrict\s+9[\s-]to[\s-]5\b/i,
  /\bfixed\s+(us|est|pst|cet|gmt)\s+hours\b/i,
  /\bdaily\s+live\s+calls\s+required\b/i,
  /\bmust\s+overlap\s+full\s+business\s+day\b/i
];
const ASYNC_HIGH = [/\basync\b/i, /\basynchronous\b/i];
const ASYNC_MED = [/\bflexible\s+hours\b/i, /\bflexible\s+schedule\b/i, /\bwork\s+across\s+time\s+zones\b/i, /\btime\s+zone\s+flexible\b/i];
const ASYNC_LOW = [/\bdistributed\s+team\b/i, /\bremote[\s-]first\b/i, /\blow\s+meeting\b/i];

const ROLE_HIGH = /\bdata\s+analyst\b|\bdata\s+scientist\b|\bbi\s+analyst\b|\bbusiness\s+intelligence\b|\bmarketing\s+analyst\b|\bgrowth\s+analyst\b|\bperformance\s+marketing\b|\bai\s+marketing\b|\bai\s+automation\b|\bai\s+workflow\b|\bmartech\b|\banalytics\s+engineer\b|\bgrowth\s+marketer\b/i;
const ROLE_MED = /\banalyst\b|\bautomation\b|\bmarketing\b|\bdata\b|\b\bai\b|\bml\b|\bmachine\s+learning\b|\bsql\b|\bpython\b|\bgrowth\b|\bperformance\b/i;

const results = [];

for (const item of $input.all()) {
  const job = item.json;
  const ai = job._ai || {};
  const desc = `${job.description || ''} ${job.location_text || ''}`.toLowerCase();
  const title = (job.job_title || '').toLowerCase();

  // Hard async reject
  if (ASYNC_REJECT.some(p => p.test(desc))) continue;

  // Async score
  let asyncLevel = 'low';
  let asyncScore = 10;
  if (ASYNC_HIGH.some(p => p.test(desc))) { asyncLevel = 'high'; asyncScore = 25; }
  else if (ASYNC_MED.some(p => p.test(desc))) { asyncLevel = 'medium'; asyncScore = 20; }
  else if (ASYNC_LOW.some(p => p.test(desc))) { asyncLevel = 'medium'; asyncScore = 15; }

  // Role score
  let roleScore = 0;
  let roleCategory = 'other';
  if (ROLE_HIGH.test(title)) { roleScore = 25; roleCategory = 'core_fit'; }
  else if (ROLE_MED.test(title)) { roleScore = 15; roleCategory = 'adjacent'; }

  // Taiwan eligibility score
  let taiwanScore = 0;
  const eligible = ai.taiwan_eligible || 'unclear';
  const locRisk = ai.location_risk || 'medium';
  if (eligible === 'yes') {
    if (/worldwide|work from anywhere|global remote|contractor|b2b/.test(desc)) taiwanScore = 40;
    else if (/apac/.test(desc)) taiwanScore = 30;
    else taiwanScore = 20;
  } else if (eligible === 'unclear') {
    if (locRisk === 'low') taiwanScore = 20;
    else if (locRisk === 'medium') taiwanScore = 10;
    else continue; // high risk + unclear = reject
  }

  // Salary score
  let salaryScore = 0;
  const sal = (job.salary || '').replace(/,/g, '');
  if (sal) {
    const nums = sal.match(/\d+/g);
    if (nums) {
      const max = Math.max(...nums.map(Number));
      // Handle annual vs monthly
      const monthly = max > 10000 ? max / 12 : max;
      if (monthly >= 5000) salaryScore = 25;
      else if (monthly >= 3000) salaryScore = 15;
      else salaryScore = 10;
    } else {
      salaryScore = 10;
    }
  }

  const score = taiwanScore + asyncScore + roleScore + salaryScore;

  const reasons = [];
  if (taiwanScore >= 40) reasons.push('worldwide/global');
  if (taiwanScore === 30) reasons.push('APAC OK');
  if (asyncLevel === 'high') reasons.push('async-first');
  if (asyncLevel === 'medium') reasons.push('flexible hours');
  if (roleScore === 25) reasons.push('perfect role match');
  if (roleScore === 15) reasons.push('adjacent role');
  if (salaryScore === 25) reasons.push('strong salary (5k+/mo)');

  results.push({ json: {
    ...job,
    taiwan_eligible: eligible,
    taiwan_reason: ai.reason || '',
    location_risk: locRisk,
    timezone_risk: ai.timezone_risk || 'medium',
    contractor_possible: ai.contractor_possible || 'unclear',
    async_level: asyncLevel,
    role_category: roleCategory,
    score,
    why_good_fit: reasons.join('; ') || 'needs manual review',
    decision: 'pending',
    application_status: 'new',
    notes: ''
  }});
}

return results;

// Extract cover letter text from Claude response and attach to job
const item = $input.first();
const job = item.json;
let coverLetter = '';
try {
  const content = job.content;
  if (Array.isArray(content) && content[0] && content[0].text) {
    coverLetter = content[0].text.trim();
  }
} catch (e) {}
return [{ json: { ...job, cover_letter_draft: coverLetter } }];

const today = new Date().toISOString().split('T')[0];
const allItems = $input.all().map(i => i.json);

// Filter to today's jobs only
const jobs = allItems.filter(j => (j.date_found || '').startsWith(today));
jobs.sort((a, b) => (Number(b.score) || 0) - (Number(a.score) || 0));

const topJobs = jobs.filter(j => (Number(j.score) || 0) >= 70);
const highScore = jobs.filter(j => (Number(j.score) || 0) >= 85);
const manualCheck = jobs.filter(j => j.taiwan_eligible === 'unclear' && (Number(j.score) || 0) >= 70);

const line = '─'.repeat(40);
let msg = `DAILY TAIWAN ELIGIBLE ASYNC REMOTE JOBS\n`;
msg += `${new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}\n`;
msg += `${line}\n`;
msg += `Found today: ${topJobs.length} eligible job(s)\n`;
if (highScore.length > 0) msg += `High priority (85+): ${highScore.length}\n`;
msg += `${line}\n\n`;

if (topJobs.length === 0) {
  msg += `No new eligible jobs found today. Try again tomorrow.\n`;
} else {
  msg += `TOP JOBS TODAY\n${line}\n\n`;
  topJobs.slice(0, 10).forEach((job, i) => {
    const star = Number(job.score) >= 85 ? ' APPLY NOW' : '';
    msg += `${i + 1}.${star} ${job.job_title}\n`;
    msg += `   Company:        ${job.company}\n`;
    msg += `   Score:          ${job.score}/100\n`;
    msg += `   Taiwan eligible: ${job.taiwan_eligible}\n`;
    msg += `   Reason:         ${job.taiwan_reason || 'N/A'}\n`;
    msg += `   Async level:    ${job.async_level}\n`;
    msg += `   Timezone risk:  ${job.timezone_risk}\n`;
    msg += `   Salary:         ${job.salary || 'Not listed'}\n`;
    msg += `   Why it fits:    ${job.why_good_fit || 'N/A'}\n`;
    msg += `   Apply:          ${job.job_url}\n\n`;
  });
}

if (manualCheck.length > 0) {
  msg += `\nMANUAL CHECK NEEDED\n${line}\n`;
  manualCheck.slice(0, 5).forEach(job => {
    msg += `• ${job.job_title} at ${job.company} (Score: ${job.score}) — ${job.job_url}\n`;
  });
  msg += '\n';
}

if (highScore.length > 0) {
  msg += `\nHIGH PRIORITY - Cover Letters Drafted\n${line}\n`;
  highScore.forEach(job => {
    msg += `APPLY: ${job.job_title} at ${job.company} (Score: ${job.score})\n       ${job.job_url}\n`;
  });
  msg += '\n';
}

msg += `\n${line}\nGood luck, Jerry.\n`;

return [{ json: {
  subject: `[Job Hunt] ${topJobs.length} eligible jobs today — ${highScore.length} high priority`,
  body: msg,
  jobCount: topJobs.length,
  highScoreCount: highScore.length
} }];
